public enum FfiError {

    
    
    case Store
    case Session
    case NoSession
    case BadPrekeySignature
    case BadKeyMaterial
    case NoIdentity
    /**
     * The sender named by the server is not the sender the message itself
     * authenticates. The message must not be shown.
     */
    case MisattributedMessage
    case BadInput
    case UntrustedPeerBundleProof(String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Store
        case 2: return .Session
        case 3: return .NoSession
        case 4: return .BadPrekeySignature
        case 5: return .BadKeyMaterial
        case 6: return .NoIdentity
        case 7: return .MisattributedMessage
        case 8: return .BadInput
        case 9: return .UntrustedPeerBundleProof(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Store:
            writeInt(&buf, Int32(1))
        
        
        case .Session:
            writeInt(&buf, Int32(2))
        
        
        case .NoSession:
            writeInt(&buf, Int32(3))
        
        
        case .BadPrekeySignature:
            writeInt(&buf, Int32(4))
        
        
        case .BadKeyMaterial:
            writeInt(&buf, Int32(5))
        
        
        case .NoIdentity:
            writeInt(&buf, Int32(6))
        
        
        case .MisattributedMessage:
            writeInt(&buf, Int32(7))
        
        
        case .BadInput:
            writeInt(&buf, Int32(8))
        
        
        case let .UntrustedPeerBundleProof(v1):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


